'use strict';
// MIDI 1.0 Quarter Frame chase (both directions) and Full Frame locate.
const mtcRates=[24,25,30000/1001,30];let mtcPieces=Array(8).fill(0),mtcExpected=null,mtcDirection=1,mtcAnchor=null,mtcStarting=false,mtcLostTimer=null,mtcOutNext=0,mtcOutOrigin=0,mtcOutPiece=0,mtcOutNibbles=Array(8).fill(0);
function mtcEncode(seconds,code=3){const fps=mtcRates[code]||30;let frame=Math.max(0,Math.floor(seconds*fps));if(code===2){const d=Math.floor(frame/17982),m=frame%17982;frame+=18*d+(m>=2?2*Math.floor((m-2)/1798):0)}const base=code===2?30:fps,ff=frame%base,ss=Math.floor(frame/base)%60,mm=Math.floor(frame/base/60)%60,hh=Math.floor(frame/base/3600)%24;return [ff&15,ff>>4,ss&15,ss>>4,mm&15,mm>>4,hh&15,(hh>>4)|(code<<1)]}
function mtcDecode(parts){const code=(parts[7]>>1)&3,base=code===2?30:mtcRates[code],ff=parts[0]|parts[1]<<4,ss=parts[2]|parts[3]<<4,mm=parts[4]|parts[5]<<4,hh=parts[6]|(parts[7]&1)<<4;if(ff>=base||ss>=60||mm>=60||hh>=24||code===2&&mm%10!==0&&ss===0&&ff<2)return null;let frames=((hh*60+mm)*60+ss)*base+ff;if(code===2){const minutes=hh*60+mm;frames-=2*(minutes-Math.floor(minutes/10))}return {seconds:frames/mtcRates[code],code,hh,mm,ss,ff}}
function mtcFullFrame(seconds,code=3){const tc=mtcDecode(mtcEncode(seconds,code));return [240,127,127,1,1,tc.hh|(code<<5),tc.mm,tc.ss,tc.ff,247]}
function mtcReadFullFrame(data){if(data.length!==10||data[0]!==240||data[1]!==127||data[3]!==1||data[4]!==1||data[9]!==247||data.slice(2,9).some(n=>!Number.isInteger(n)||n<0||n>127))return null;const [hr,mm,ss,ff]=data.slice(5,9);return mtcDecode([ff&15,ff>>4,ss&15,ss>>4,mm&15,mm>>4,hr&15,((hr&16)>>4)|((hr>>5)<<1)])}
function mtcTransportDirection(){return midiConfig.mtcIn&&mtcAnchor?mtcDirection:1}
function mtcStartTransport(time,initialStep=0){if(midiConfig.mtcOut&&!midiConfig.mtcIn&&typeof midiAccess!=='undefined'&&midiAccess?.sysexEnabled)midiSend(mtcFullFrame(initialStep*60/tempo()/4,midiConfig.mtcRate??3),time);mtcOutOrigin=time-initialStep*60/tempo()/4;mtcOutNext=time;mtcOutPiece=0}
function mtcOutputStep(time,dt){if(!midiConfig.mtcOut||midiConfig.mtcIn||!midiOutputPort)return;const code=midiConfig.mtcRate??3,interval=1/(mtcRates[code]*4);if(mtcOutNext<time-.2){mtcOutNext=time;mtcOutPiece=0}while(mtcOutNext<time+dt-.00001){if(mtcOutPiece===0)mtcOutNibbles=mtcEncode(Math.max(0,mtcOutNext-mtcOutOrigin),code);midiSend([241,(mtcOutPiece<<4)|mtcOutNibbles[mtcOutPiece]],mtcOutNext);mtcOutPiece=(mtcOutPiece+1)%8;mtcOutNext+=interval}}
function mtcAlignTransport(){if(!mtcAnchor||!ctx)return;const dt=60/tempo()/4,direction=mtcTransportDirection(),seconds=Math.max(0,mtcAnchor.seconds+direction*(ctx.currentTime-mtcAnchor.at)),boundary=direction===1?Math.ceil(seconds/dt):Math.floor(seconds/dt);step=((boundary%sequenceLength())+sequenceLength())%sequenceLength();nextTime=ctx.currentTime+Math.max(0,direction*(boundary*dt-seconds));scheduled.length=0}
function stopMTCWatchdog(){clearTimeout(mtcLostTimer);mtcLostTimer=null}
function handleMTC(data){if(data[0]===240){const tc=mtcReadFullFrame(data);if(!tc)return false;if(!midiConfig.mtcIn)return true;resetMTCInput();if(playing||mtcStarting)stop(true);mtcAnchor={seconds:tc.seconds,at:ctx?.currentTime||0};mtcAlignTransport();resumeStep=step;sequencePage=Math.floor(step/barSteps());renderSteps();$('#mtcState').textContent='MTC positionné · '+[tc.hh,tc.mm,tc.ss,tc.ff].map(n=>String(n).padStart(2,'0')).join(':')+' · en attente du timecode';return true}if(data[0]!==241)return false;if(!midiConfig.mtcIn)return true;const b=data[1],piece=(b>>4)&7;if(!Number.isInteger(b)||b<0||b>127)return true;stopMTCWatchdog();mtcLostTimer=setTimeout(()=>{mtcExpected=null;mtcAnchor=null;if(playing||mtcStarting){stop(true);status('MTC interrompu : lecture arrêtée.')}},350);if(mtcExpected===null||piece!==mtcExpected){mtcExpected=null;if(piece===0||piece===7){mtcDirection=piece===0?1:-1;mtcPieces[piece]=b&15;mtcExpected=piece+mtcDirection}return true}mtcPieces[piece]=b&15;const complete=mtcDirection===1?piece===7:piece===0;mtcExpected=(piece+mtcDirection+8)%8;if(!complete)return true;const tc=mtcDecode(mtcPieces);if(!tc)return true;const current=ctx?.currentTime||0;mtcAnchor={seconds:Math.max(0,tc.seconds+mtcDirection*2/mtcRates[tc.code]),at:current};$('#mtcState').textContent='MTC '+[tc.hh,tc.mm,tc.ss,tc.ff].map(n=>String(n).padStart(2,'0')).join(':')+' · '+mtcRates[tc.code].toFixed(2)+' fps · '+(mtcDirection===1?'avant':'arrière (ordre des notes)');if(!playing&&!mtcStarting){if($('#songEnabled').checked){status('MTC : désactivez le morceau pour suivre la séquence sélectionnée.');return true}mtcStarting=true;externalTransport=true;$('#play').onclick().finally(()=>{externalTransport=false;mtcStarting=false})}else if(playing){const dt=60/tempo()/4,last=scheduled.filter(e=>e.time<=current).at(-1);if(last){const length=sequenceLength()*dt,expected=mtcAnchor.seconds%length,actual=((last.step*dt+mtcDirection*(current-last.time))%length+length)%length,drift=((actual-expected+length*1.5)%length)-length*.5;if(Math.abs(drift)>.12||last.direction!==mtcDirection){for(const v of voices)if(v.time>current)try{v.source.stop()}catch{}epoch++;mtcAlignTransport()}}}return true}

function resetMTCInput(){stopMTCWatchdog();mtcAnchor=null;mtcExpected=null;mtcDirection=1}
